<!doctype html>
<html lang="es">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=1920,height=1080,initial-scale=1">
    <title>{{ $competition->tournament->name }} · Transmisión</title>
    <style>
        :root{--navy:#071421;--blue:#315a7d;--green:#07844d;--accent:#7895af;--line:#33495d;--white:#f2f6f8;--muted:#91a4b5}*{box-sizing:border-box}html,body{width:1920px;height:180px;margin:0;overflow:hidden;background:transparent;font-family:Inter,Arial,sans-serif;color:var(--white)}body{background:linear-gradient(100deg,#07111c 0%,#0c1e2e 55%,#081724 100%)}#stage{position:relative;width:1920px;height:180px;border-top:4px solid var(--accent);border-bottom:4px solid var(--blue);overflow:hidden}.slide{display:grid;grid-template-columns:315px 1fr;height:172px;animation:enter .45s ease both}.identity{display:flex;flex-direction:column;justify-content:center;padding:14px 20px;background:linear-gradient(120deg,#17334e,#0d263a);border-right:2px solid var(--accent)}.live{display:flex;align-items:center;gap:8px;color:#bdd0df;font-size:13px;font-weight:900;letter-spacing:.13em;text-transform:uppercase}.live:before{content:"";width:10px;height:10px;border-radius:50%;background:#d75b68;box-shadow:0 0 0 5px rgba(215,91,104,.16);animation:pulse 1.4s infinite}.tournament{margin-top:9px;font-size:24px;font-weight:1000;line-height:1.05;text-transform:uppercase}.counter{margin-top:9px;color:#b9cee5;font-size:12px}.content{display:grid;grid-template-rows:43px 1fr;padding:7px 14px 8px}.heading{display:flex;align-items:center;gap:14px;min-width:0}.phase{font-size:21px;font-weight:1000;text-transform:uppercase}.context{padding:5px 10px;border-radius:999px;background:#284e70;color:#fff;font-size:13px;font-weight:900}.updated{margin-left:auto;color:var(--muted);font-size:12px}.zone-layout{display:grid;grid-template-columns:1.55fr .95fr;gap:12px;min-height:0}.matches{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px}.match{min-width:0;padding:6px 9px;border:1px solid var(--line);border-left:5px solid #71849a;border-radius:7px;background:rgba(14,36,62,.94)}.match.called{border-color:#e4a900;border-left-color:#e4a900;background:#3b3215;box-shadow:0 0 0 2px rgba(228,169,0,.2)}.match.called .match-title,.match.called .table{color:#fff4c2}.match.in_progress{border-color:#07844d;border-left-color:#07844d;background:#11392a;box-shadow:0 0 0 2px rgba(7,132,77,.2)}.match.in_progress .match-title,.match.in_progress .table{color:#e5fff2}.match.completed{border-left-color:#5f87ad;background:rgba(18,51,75,.94)}.match-title{display:flex;justify-content:space-between;gap:8px;color:#9bb7ce;font-size:10px;font-weight:900;text-transform:uppercase}.table{color:#c7d7e3}.player{display:flex;justify-content:space-between;gap:7px;padding-top:3px;font-size:12px;font-weight:800;white-space:nowrap;overflow:hidden}.player span:first-child{overflow:hidden;text-overflow:ellipsis}.player.winner{color:#5aeda7}.score{flex:none;font-size:13px}.standings{width:100%;border-collapse:collapse;background:rgba(7,22,40,.8);font-size:10px}.standings th{padding:4px;background:#2f725d;color:#fff;text-transform:uppercase}.standings td{padding:4px 6px;border:1px solid #2d4561;text-align:center}.standings td:nth-child(2){max-width:180px;text-align:left;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.bracket-layout{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:9px;align-items:center}.empty{display:grid;place-items:center;height:100%;color:var(--muted);font-size:18px}.progress{position:absolute;left:0;bottom:0;height:4px;background:var(--accent);animation:progress linear both}@keyframes enter{from{opacity:0;transform:translateX(28px)}to{opacity:1;transform:none}}@keyframes pulse{50%{opacity:.45}}@keyframes progress{from{width:0}to{width:100%}}
        html,body{width:1920px;height:1080px}
        #stage{width:1920px;height:1080px;border-top-width:8px;border-bottom-width:8px}
        .slide{grid-template-columns:1fr;grid-template-rows:104px 1fr;height:1064px}
        .identity{flex-direction:row;align-items:center;justify-content:flex-start;gap:24px;padding:10px 34px;border-right:0;border-bottom:4px solid var(--accent)}
        .live{flex:none;gap:14px;font-size:20px}.live:before{width:16px;height:16px;box-shadow:0 0 0 8px rgba(255,60,79,.18)}
        .tournament-logo{width:70px;height:70px;flex:none;object-fit:contain;border-radius:10px;background:rgba(255,255,255,.06);padding:4px}.tournament{margin:0;font-size:32px;line-height:1.08}.tournament-data{display:flex;align-items:center;gap:24px;margin-left:auto;color:#d5e2f0;font-size:14px}.tournament-data span{display:flex;flex-direction:column;gap:3px;max-width:250px}.tournament-data small{color:#8fa9bf;font-size:9px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}.tournament-data b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px}
        .counter{margin-top:26px;font-size:20px}
        .content{grid-template-rows:76px 1fr;padding:16px 28px 28px}
        .heading{gap:24px}.phase{font-size:34px}.context{padding:9px 17px;font-size:20px}.updated{font-size:17px}
        .zone-layout{grid-template-columns:1.35fr .65fr;gap:24px}
        .matches{grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:repeat(3,minmax(0,1fr));gap:18px}
        .match{display:flex;flex-direction:column;justify-content:center;padding:20px 24px;border-width:2px;border-left-width:9px;border-radius:14px}
        .match-title{font-size:18px}.player{padding-top:15px;font-size:26px}.score{font-size:29px}
        .standings{font-size:20px}.standings th{padding:16px}.standings td{padding:18px 14px;border-width:2px}.standings td:nth-child(2){max-width:360px}
        .bracket-layout{grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:repeat(2,minmax(0,1fr));gap:24px}
        .empty{font-size:32px}.progress{height:8px}
        .zones-grid{display:grid;gap:18px;min-height:0;align-content:start;align-items:start}.zone-panel{display:grid;grid-template-rows:52px auto;min-width:0;overflow:hidden;border:2px solid #33495d;border-radius:14px;background:rgba(8,25,39,.9)}.zone-name{display:flex;align-items:center;justify-content:space-between;padding:0 17px;background:#284e70;font-size:20px;font-weight:1000;text-transform:uppercase}.zone-card-body{padding:11px}.zone-bracket-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:repeat(3,104px);gap:8px 12px;align-items:stretch}.mini-match{display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-rows:auto auto auto;gap:3px 8px;align-content:center;min-width:0;padding:8px 10px;border:1px solid #33495d;border-left:5px solid #71849a;border-radius:7px;background:#112a40}.mini-match.called{position:relative;z-index:2;border-color:#e4a900;border-left-color:#e4a900;background:#3b3215;box-shadow:0 0 0 2px rgba(228,169,0,.2)}.mini-match.called .mini-title,.mini-match.called .table{color:#fff4c2}.mini-match.in_progress{position:relative;z-index:2;border-color:#07844d;border-left-color:#07844d;background:#11392a;box-shadow:0 0 0 2px rgba(7,132,77,.2)}.mini-match.in_progress .mini-title,.mini-match.in_progress .table{color:#e5fff2}.mini-match.completed{border-left-color:#5f87ad}.mini-title{grid-column:1/-1;display:flex;justify-content:space-between;gap:6px;color:#9bb7ce;font-size:9px;font-weight:900;text-transform:uppercase}.mini-player{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px;font-weight:850}.mini-player.winner{color:#5aeda7}.mini-score{font-size:12px}.z-m1{grid-column:1;grid-row:1}.z-m2{grid-column:1;grid-row:2}.z-loss{grid-column:1;grid-row:3}.z-win{grid-column:2;grid-row:1}.z-second{grid-column:2;grid-row:3}.zone-place{display:flex;flex-direction:column;align-items:center;justify-content:center;min-width:0;padding:8px;border:2px solid #466d91;border-radius:8px;background:#0e2132;text-align:center}.zone-place small{color:#86a6c1;font-size:9px;font-weight:900;text-transform:uppercase}.zone-place strong{display:block;max-width:100%;margin-top:5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px}.z-first-place{grid-column:3;grid-row:1}.z-runner-place{grid-column:3;grid-row:3}.zone-standings{grid-column:2/4;grid-row:2;width:100%;height:100%;border-collapse:collapse;background:#071421;font-size:9px}.zone-standings th{height:19px;padding:2px 4px;background:#2f725d}.zone-standings td{height:20px;padding:2px 5px;border:1px solid #2d4356;text-align:center}.zone-standings td:nth-child(2){max-width:270px;text-align:left;font-weight:850;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.zones-grid.dense{gap:12px}.zones-grid.dense .zone-panel{grid-template-rows:34px auto;border-radius:9px}.zones-grid.dense .zone-name{padding:0 10px;font-size:14px}.zones-grid.dense .zone-card-body{padding:6px}.zones-grid.dense .zone-bracket-grid{grid-template-rows:repeat(3,64px);gap:4px 6px}.zones-grid.dense .mini-match{padding:3px 5px;border-radius:5px}.zones-grid.dense .mini-title,.zones-grid.dense .zone-place small{font-size:7px}.zones-grid.dense .mini-player,.zones-grid.dense .mini-score,.zones-grid.dense .zone-place strong,.zones-grid.dense .zone-standings{font-size:8px}.zones-grid.dense .zone-standings th,.zones-grid.dense .zone-standings td{height:12px;padding:1px 3px}
        .content{grid-template-rows:48px 1fr;padding-top:10px}.heading{gap:12px}.phase{font-size:23px}.context{padding:6px 12px;font-size:16px}.zone-panel{grid-template-rows:44px auto}.zone-name{justify-content:flex-start;font-size:19px}.zone-bracket-grid{grid-template-rows:repeat(3,132px);gap:10px 12px}.mini-match{padding:12px 12px}.mini-title{font-size:10px}.mini-player,.mini-score{font-size:15px}.zone-place small{font-size:10px}.zone-place strong{font-size:15px}.zone-standings{font-size:10px}.zone-standings th{height:24px}.zone-standings td{height:26px}.zones-grid.dense .zone-panel{grid-template-rows:34px auto}.zones-grid.dense .zone-bracket-grid{grid-template-rows:repeat(3,64px)}.zones-grid.dense .mini-match{padding:3px 5px}.zones-grid.dense .mini-title,.zones-grid.dense .zone-place small{font-size:7px}.zones-grid.dense .mini-player,.zones-grid.dense .mini-score,.zones-grid.dense .zone-place strong,.zones-grid.dense .zone-standings{font-size:8px}.zones-grid.dense .zone-standings th,.zones-grid.dense .zone-standings td{height:12px}
        .zones-grid:not(.multi-row) .zone-bracket-grid{grid-template-rows:repeat(3,104px)}.zones-grid.multi-row{gap:12px}.zones-grid.multi-row .zone-panel{grid-template-rows:40px auto}.zones-grid.multi-row .zone-name{font-size:17px}.zones-grid.multi-row .zone-card-body{padding:8px}.zones-grid.multi-row .zone-bracket-grid{grid-template-rows:repeat(3,112px);gap:8px 10px}.zones-grid.multi-row .mini-match{padding:8px 9px}.zones-grid.multi-row .mini-player,.zones-grid.multi-row .mini-score,.zones-grid.multi-row .zone-place strong{font-size:13px}.zones-grid.multi-row .zone-standings{font-size:9px}.zones-grid.multi-row .zone-standings th{height:21px}.zones-grid.multi-row .zone-standings td{height:22px}.zones-grid.crowded .zone-panel{grid-template-rows:32px auto}.zones-grid.crowded .zone-name{font-size:13px}.zones-grid.crowded .zone-card-body{padding:5px}.zones-grid.crowded .zone-bracket-grid{grid-template-rows:repeat(3,62px);gap:4px 6px}.zones-grid.crowded .mini-match{padding:3px 5px}.zones-grid.crowded .mini-title,.zones-grid.crowded .zone-place small{font-size:7px}.zones-grid.crowded .mini-player,.zones-grid.crowded .mini-score,.zones-grid.crowded .zone-place strong,.zones-grid.crowded .zone-standings{font-size:8px}.zones-grid.crowded .zone-standings th,.zones-grid.crowded .zone-standings td{height:12px;padding:1px 3px}
        .zone-tabs{display:flex;align-items:center;gap:6px;min-width:0;margin-left:8px;overflow:hidden}.zone-tab{flex:0 1 auto;min-width:54px;padding:6px 10px;border:1px solid #33495d;border-radius:999px;background:#10263a;color:#91a4b5;font-size:11px;font-weight:900;text-align:center;white-space:nowrap}.zone-tab.active{border-color:#7895af;background:#315a7d;color:#fff}.zones-grid.single-zone{display:grid;grid-template-columns:1fr;place-items:center;width:100%;height:100%;min-height:0}.zones-grid.single-zone .zone-panel{grid-template-rows:50px auto;width:min(1500px,100%);justify-self:center;align-self:center}.zones-grid.single-zone .zone-name{font-size:23px}.zones-grid.single-zone .zone-card-body{padding:14px}.zones-grid.single-zone .zone-bracket-grid{grid-template-rows:repeat(3,170px);gap:14px 22px}.zones-grid.single-zone .mini-match{padding:16px 18px;border-left-width:7px}.zones-grid.single-zone .mini-title{font-size:14px}.zones-grid.single-zone .mini-player,.zones-grid.single-zone .mini-score{font-size:22px}.zones-grid.single-zone .zone-place small{font-size:13px}.zones-grid.single-zone .zone-place strong{font-size:21px}.zones-grid.single-zone .zone-standings{font-size:14px}.zones-grid.single-zone .zone-standings th{height:34px}.zones-grid.single-zone .zone-standings td{height:34px;padding:4px 8px}
        .planned-phase{display:grid;place-items:center;height:100%}.planned-card{width:min(1050px,90%);padding:50px;border:2px solid #33495d;border-radius:18px;background:#10263a;text-align:center}.planned-card small{display:block;color:#91a4b5;font-size:18px;font-weight:900;text-transform:uppercase}.planned-card strong{display:block;margin-top:18px;font-size:42px}.planned-card p{margin:18px 0 0;color:#bdd0df;font-size:22px}
        .content,.knockout-bracket,.knockout-column{min-height:0}.knockout-bracket{display:grid;grid-template-columns:repeat(var(--bracket-columns),minmax(0,1fr));gap:8px;height:100%;overflow:hidden;padding:0 2px}.knockout-column{position:relative;display:grid;grid-template-rows:repeat(var(--base-count),minmax(0,1fr));min-width:0;height:100%}.knockout-column .match{position:relative;display:flex;flex-direction:column;justify-content:center;align-self:center;width:100%;height:min(56px,calc(100% - 6px));min-height:0;padding:3px 5px;overflow:hidden;border-left-width:3px;border-radius:5px}.knockout-column .match-title{position:absolute;z-index:2;top:2px;right:4px;padding:1px 3px;border-radius:3px;background:rgba(7,20,33,.78);font-size:5px;line-height:1}.knockout-column .match-title+.player{padding-right:35px}.knockout-column .player{padding-top:2px;font-size:9px;line-height:1.08}.knockout-column .player>span{display:flex;align-items:center;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:900}.knockout-column .player .seed{flex:none;min-width:15px;color:#8fb1cc}.knockout-column .score{font-size:9px}.knockout-column.right .match{border-left-width:1px;border-right:3px solid #71849a}.knockout-column.right .player{flex-direction:row-reverse}.knockout-column.right .player>span{justify-content:flex-end;text-align:right}.knockout-column.left .match:after,.knockout-column.right .match:before{content:"";position:absolute;top:50%;width:9px;border-top:2px solid #46647e}.knockout-column.left .match:after{right:-10px}.knockout-column.right .match:before{left:-10px}.knockout-final .match{height:min(76px,calc(100% - 8px));border-color:#7895af;border-left-color:#7895af;background:#17334e}.knockout-final .player{padding-top:4px;font-size:11px}.knockout-bracket.dense{gap:5px}.knockout-bracket.dense .match{height:calc(100% - 5px);padding:1px 3px}.knockout-bracket.dense .match-title{font-size:4px}.knockout-bracket.dense .player,.knockout-bracket.dense .score{font-size:8px;line-height:1}.knockout-bracket.dense .knockout-final .match{height:min(60px,calc(100% - 6px))}
        .bracket-stage{position:relative;grid-row:1/-1;min-height:0;height:100%;overflow:hidden}.bracket-stage .knockout-bracket{position:relative;z-index:1}.bracket-brand{position:absolute;z-index:3;left:50%;top:13%;display:flex;flex-direction:column;align-items:center;transform:translateX(-50%);pointer-events:none;text-align:center}.bracket-trophy{font-size:58px;line-height:1;filter:drop-shadow(0 5px 14px rgba(0,0,0,.45))}.bracket-name{margin-top:8px;color:#dce8f1;font-size:22px;font-weight:1000;letter-spacing:.06em;text-transform:uppercase;text-shadow:0 3px 12px #071421}.knockout-column .match-title:empty{display:none}.knockout-column .match-title{justify-content:flex-end}
        html,body{width:100vw;height:100vh;overflow:hidden}#stage{position:absolute;left:50%;top:50%;transform-origin:center center}
    </style>
</head>
<body>
<main id="stage"><div class="empty">Cargando resultados en vivo…</div></main>
<script>
const endpoint=@json($jsonUrl),config=@json($broadcastConfig),stage=document.querySelector('#stage');
let data=null,slides=[],activeSlide=0,lastPayload='',loading=false,rotationTimer=null;
function fitStage(){const scale=Math.min(window.innerWidth/1920,window.innerHeight/1080);stage.style.transform='translate(-50%,-50%) scale('+scale+')'}
const esc=value=>String(value??'—').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
const stateLabel=state=>({pending:'Pendiente',ready:'Preparada',in_progress:'En curso',completed:'Finalizada'}[state]||state);
const scheduleDate=schedule=>schedule.starts_at?new Intl.DateTimeFormat('es-AR',{dateStyle:'short',timeStyle:'short'}).format(new Date(schedule.starts_at)):'';
const matchState=match=>['called','in_progress','completed'].includes(match.estado)?match.estado:'';
const score=(match,side)=>{if(match.estado!=='completed'&&match.estado!=='in_progress')return '—';const values=match.sets_computables||[];return esc(values[side]??'—')};
function identity(){return '<header class="identity">'+(data.logo?'<img class="tournament-logo" src="'+esc(data.logo)+'" alt="Logo del torneo">':'')+'<div class="live">Resultados en vivo</div><div class="tournament">'+esc(data.torneo)+'</div><div class="tournament-data"><span><small>Sede</small><b>'+esc(data.sede||'Sin informar')+'</b></span><span><small>Fecha</small><b>'+esc(data.fecha||'Sin informar')+'</b></span><span><small>Tipo</small><b>'+esc([data.tipo_torneo,data.caracter].filter(Boolean).join(' · ')||'Sin informar')+'</b></span><span><small>Modalidad</small><b>'+esc(data.modalidad||'Sin informar')+'</b></span></div></header>'}
function matchCard(match,style='',side='left'){const winner=match.ganador||'',player=(number,name,scoreValue,isWinner)=>side==='right'?'<div class="player '+(isWinner?'winner':'')+'"><span>'+esc(name)+' · <strong class="seed">'+esc(number||'—')+'</strong></span><b class="score">'+scoreValue+'</b></div>':'<div class="player '+(isWinner?'winner':'')+'"><span><strong class="seed">'+esc(number||'—')+'</strong> · '+esc(name)+'</span><b class="score">'+scoreValue+'</b></div>';return '<article class="match '+matchState(match)+'"'+(style?' style="'+style+'"':'')+'>'+(match.mesa?'<div class="match-title"><span class="table">Mesa '+esc(match.mesa)+'</span></div>':'')+player(match.numero_1,match.jugador_1||match.placeholder_1||'A designar',score(match,0),winner===match.jugador_1)+player(match.numero_2,match.jugador_2||match.placeholder_2||'A designar',score(match,1),winner===match.jugador_2)+'</article>'}
function zoneMatchPosition(match){const label=String(match.etiqueta||'').toLocaleLowerCase('es');if(label==='partido 1')return'z-m1';if(label==='partido 2')return'z-m2';if(label.includes('primer puesto'))return'z-win';if(label.includes('segundo puesto'))return'z-second';if(label.includes('perdedores')||label.includes('recuperación'))return'z-loss';return''}
function miniMatchCard(match){const winner=match.ganador||'';return '<article class="mini-match '+zoneMatchPosition(match)+' '+matchState(match)+'"><div class="mini-title"><span>'+esc(match.etiqueta||('Ronda '+match.ronda))+'</span>'+(match.mesa?'<span class="table">Mesa '+esc(match.mesa)+'</span>':'')+'</div><span class="mini-player '+(winner===match.jugador_1?'winner':'')+'">'+esc(match.jugador_1||'A definir')+'</span><b class="mini-score">'+score(match,0)+'</b><span class="mini-player '+(winner===match.jugador_2?'winner':'')+'">'+esc(match.jugador_2||'A definir')+'</span><b class="mini-score">'+score(match,1)+'</b></article>'}
function zonePanel(phase,zone){const matches=phase.partidos.filter(match=>Number(match.zona_id)===Number(zone.id)),standings=zone.jugadores.slice().sort((a,b)=>(a.clasificacion||99)-(b.clasificacion||99)),first=standings.find(row=>Number(row.clasificacion)===1)?.nombre||'A definir',second=standings.find(row=>Number(row.clasificacion)===2)?.nombre||'A definir';return '<section class="zone-panel"><div class="zone-name"><span>'+esc(zone.nombre)+'</span></div><div class="zone-card-body"><div class="zone-bracket-grid">'+matches.map(miniMatchCard).join('')+'<div class="zone-place z-first-place"><small>1.er puesto</small><strong>'+esc(first)+'</strong></div><table class="zone-standings"><thead><tr><th>Pos</th><th>Jugador</th><th>PG</th><th>DS</th><th>Prom</th></tr></thead><tbody>'+standings.map(row=>'<tr><td>'+esc(row.clasificacion)+'</td><td>'+esc(row.nombre)+'</td><td>'+esc(row.partidos_ganados)+'</td><td>'+esc(row.diferencia_sets)+'</td><td>'+esc(row.promedio)+'</td></tr>').join('')+'</tbody></table><div class="zone-place z-runner-place"><small>2.º puesto</small><strong>'+esc(second)+'</strong></div></div></div></section>'}
function zoneScheduleSlides(phase,slotKey,zones){return zones.map((zone,index)=>({key:'zones-'+phase.id+'-'+slotKey+'-'+zone.id,html:'<div class="heading"><div class="phase">'+esc(phase.nombre)+'</div><div class="context">'+esc(zone.horario||'Sin horario')+'</div><div class="zone-tabs">'+zones.map((item,itemIndex)=>'<span class="zone-tab '+(itemIndex===index?'active':'')+'">'+esc(item.nombre)+'</span>').join('')+'</div></div><div class="zones-grid single-zone">'+zonePanel(phase,zone)+'</div>'}))}
function scheduleMatches(phase,schedule){return phase.partidos.filter(match=>{if(Number(match.ronda)!==Number(schedule.round_number))return false;const from=Number(schedule.from_match||0),to=Number(schedule.to_match||0);return (!from||Number(match.orden)>=from)&&(!to||Number(match.orden)<=to)})}
function bracketColumn(matches,side,baseCount){const span=Math.max(1,Math.floor(baseCount/Math.max(1,matches.length)));return '<section class="knockout-column '+side+'">'+matches.map((match,index)=>matchCard(match,'grid-row:'+(index*span+1)+' / span '+span,side)).join('')+'</section>'}
function knockoutBracket(phase){const ordered=phase.partidos.slice().sort((a,b)=>Number(a.ronda)-Number(b.ronda)||Number(a.orden)-Number(b.orden)),roundNumbers=[...new Set(ordered.map(match=>Number(match.ronda)))].sort((a,b)=>a-b);if(!roundNumbers.length)return'';const firstRound=ordered.filter(match=>Number(match.ronda)===roundNumbers[0]),baseCount=Math.max(1,Math.ceil(firstRound.length/2)),lastRound=roundNumbers.at(-1),left=[],right=[];roundNumbers.filter(round=>round!==lastRound).forEach(round=>{const matches=ordered.filter(match=>Number(match.ronda)===round),half=Math.ceil(matches.length/2);left.push(bracketColumn(matches.slice(0,half),'left',baseCount));right.unshift(bracketColumn(matches.slice(half),'right',baseCount))});const finalMatches=ordered.filter(match=>Number(match.ronda)===lastRound),finalSpan=Math.max(1,Math.floor(baseCount/Math.max(1,finalMatches.length))),center='<section class="knockout-column knockout-final">'+finalMatches.map((match,index)=>matchCard(match,'grid-row:'+(index*finalSpan+1)+' / span '+finalSpan,'center')).join('')+'</section>',columns=left.length+1+right.length,dense=baseCount>8||columns>9?' dense':'';return '<div class="knockout-bracket'+dense+'" style="--bracket-columns:'+columns+';--base-count:'+baseCount+'">'+left.join('')+center+right.join('')+'</div>'}
function bracketSlides(phase){if(!phase.partidos.length)return[{key:'phase-'+phase.id+'-planned',html:'<div class="heading"><div class="phase">'+esc(phase.nombre)+'</div></div><div class="planned-phase"><div class="planned-card"><small>'+esc(stateLabel(phase.estado))+'</small><strong>Grilla a preparar</strong><p>Enfrentamientos a definir</p></div></div>'}];return[{key:'phase-'+phase.id+'-bracket',html:'<div class="bracket-stage"><div class="bracket-brand"><div class="bracket-trophy" aria-hidden="true">🏆</div><div class="bracket-name">'+esc(phase.nombre)+'</div></div>'+knockoutBracket(phase)+'</div>'}]}
function buildSlides(){const allowedPhases=(config.allPhases?data.fases:data.fases.filter(phase=>config.phaseIds.includes(Number(phase.id))));slides=allowedPhases.flatMap(phase=>{if(phase.tipo!=='zones')return bracketSlides(phase);const zones=config.allZoneSlots?phase.zonas:phase.zonas.filter(zone=>(config.zoneSlotKeys||[]).includes(String(zone.horario_clave))),bySlot=zones.reduce((groups,zone)=>{(groups[String(zone.horario_clave||'without_slot')]??=[]).push(zone);return groups},{});return Object.entries(bySlot).flatMap(([slotKey,slotZones])=>zoneScheduleSlides(phase,slotKey,slotZones))});if(activeSlide>=slides.length)activeSlide=0}
function restartRotation(){if(rotationTimer){clearInterval(rotationTimer);rotationTimer=null}if(slides.length)rotationTimer=setInterval(()=>{if(!slides.length)return;activeSlide=(activeSlide+1)%slides.length;showSlide()},config.rotationSeconds*1000)}
function showSlide(){if(!config.enabled){stage.innerHTML='<div class="empty">La transmisión está deshabilitada.</div>';restartRotation();return}if(!slides.length){stage.innerHTML='<div class="empty">No hay contenido seleccionado para la transmisión.</div>';restartRotation();return}const slide=slides[activeSlide];stage.innerHTML='<section class="slide">'+identity()+'<div class="content">'+slide.html+'</div></section><div class="progress" style="animation-duration:'+config.rotationSeconds+'s"></div>';if(!rotationTimer)restartRotation()}
function syncConfig(transmission){if(!transmission)return false;const next={enabled:Boolean(transmission.habilitada),allPhases:Boolean(transmission.todas_fases),phaseIds:(transmission.fases||[]).map(Number),allZoneSlots:Boolean(transmission.todos_horarios_zonas),zoneSlotKeys:(transmission.horarios_zonas||[]).map(String),rotationSeconds:Math.max(4,Math.min(60,Number(transmission.segundos||8)))};const changed=JSON.stringify(next)!==JSON.stringify({enabled:config.enabled??true,allPhases:config.allPhases,phaseIds:config.phaseIds,allZoneSlots:config.allZoneSlots,zoneSlotKeys:config.zoneSlotKeys,rotationSeconds:config.rotationSeconds});Object.assign(config,next);return changed}
async function refresh(){if(loading)return;loading=true;try{const separator=endpoint.includes('?')?'&':'?',response=await fetch(endpoint+separator+'_='+Date.now(),{cache:'no-store',headers:{Accept:'application/json'}});if(!response.ok)throw new Error('No fue posible obtener los resultados');const payload=await response.json(),signature=JSON.stringify(payload.data),configChanged=syncConfig(payload.data.transmision);if(signature!==lastPayload||configChanged){const currentKey=slides[activeSlide]?.key;lastPayload=signature;data=payload.data;buildSlides();const sameIndex=slides.findIndex(slide=>slide.key===currentKey);if(sameIndex>=0)activeSlide=sameIndex;if(configChanged)restartRotation();showSlide()}}catch(error){if(!data)stage.innerHTML='<div class="empty">'+esc(error.message)+'</div>'}finally{loading=false}}
fitStage();refresh();window.addEventListener('resize',fitStage);setInterval(()=>{if(!document.hidden)refresh()},4000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});
</script>
</body>
</html>
